-- Vyapar parity Phase 5 follow-up: §194A TDS at credit. Interest credited to a lender before it is paid, and what each
-- payment settles of it. Additive. Generated by drizzle-kit; RLS and checks below added by hand.
CREATE TABLE "loan_interest_credits" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"deleted_at" timestamp with time zone,
	"business_id" uuid NOT NULL,
	"loan_id" uuid NOT NULL,
	"date" date NOT NULL,
	"amount" numeric(14, 2) NOT NULL,
	"tds_amount" numeric(14, 2) DEFAULT 0 NOT NULL,
	"tds_base" numeric(14, 2) DEFAULT 0 NOT NULL,
	"tds_rate" numeric(14, 2) DEFAULT 0 NOT NULL,
	"notes" text DEFAULT '' NOT NULL
);
